<script setup lang="ts">import {Link,router} from '@inertiajs/vue3';import AdminLayout from '@/Layouts/AdminLayout.vue';import PageMeta from '@/Components/PageMeta.vue';import EmptyState from '@/Components/EmptyState.vue';import Pagination from '@/Components/Pagination.vue';import type {Doctor,Paginated} from '@/types';defineProps<{doctors:Paginated<Doctor>}>();const activate=(item:Doctor)=>router.patch(route('admin.doctors.activation',item.id),{active:!item.is_active},{preserveScroll:true});</script>
<template><AdminLayout title="Cuerpo médico" eyebrow="Catálogos"><PageMeta title="Catálogo médico" noindex/><section class="admin-content"><div class="content-toolbar"><div><p class="kicker">Profesionales</p><h2>{{ doctors.total }} perfiles</h2></div><Link class="button button--admin" :href="route('admin.doctors.create')">+ Nuevo médico</Link></div><div class="panel table-panel"><div v-if="doctors.data.length" class="table-scroll"><table><thead><tr><th>Profesional</th><th>Credencial</th><th>Especialidades</th><th>Publicación</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in doctors.data" :key="item.id"><td><strong>{{ item.professional_name||`${item.last_name}, ${item.first_name}` }}</strong><small>{{ item.email||'Sin correo registrado' }}</small></td><td>{{ [item.credential_type,item.credential_number].filter(Boolean).join(' ')||'Pendiente' }}</td><td>{{ item.specialties?.map(s=>s.name).join(', ')||'Sin asignar' }}</td><td>{{ item.is_public?'Público':'No público' }}</td><td><span :class="['catalog-state',item.is_active?'on':'off']">{{ item.is_active?'Activo':'Inactivo' }}</span></td><td><div class="row-actions"><Link class="row-action" :href="route('admin.doctors.edit',item.id)">Editar</Link><button class="row-action" type="button" @click="activate(item)">{{ item.is_active?'Desactivar':'Activar' }}</button></div></td></tr></tbody></table></div><EmptyState v-else title="No hay perfiles médicos configurados"/><Pagination :links="doctors.links"/></div></section></AdminLayout></template>
